begin;

-- Generated by `supabase migration new exclusive_portal_account_status_executor`
-- at 20260922084032. Normalised to the allocated forward version because the
-- existing migration history already ends at 20260922200000.
-- Drain old application executions before rollout. Existing pending claims
-- have no trustworthy external-write receipt and must remain fenced until an
-- operator verifies the old executors/provider requests have actually ended.
alter table private.portal_account_status_change_claims
  add column provider_status text not null default 'not_started'
    check (provider_status in ('not_started', 'executing', 'succeeded', 'unknown')),
  add column executor_token uuid,
  add column provider_started_at timestamptz,
  add column provider_finished_at timestamptz;

update private.portal_account_status_change_claims
set provider_status = 'unknown'
where status = 'pending';

create function private.guard_portal_account_status_executor()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.change_token is distinct from old.change_token then
    if old.status = 'pending' then
      raise exception 'An account status change requires reconciliation.' using errcode = '40001';
    end if;
    new.provider_status := 'not_started';
    new.executor_token := null;
    new.provider_started_at := null;
    new.provider_finished_at := null;
  elsif old.status = 'pending' and new.status = 'finalised'
    and old.provider_status <> 'succeeded' then
    raise exception 'The login provider has not confirmed completion.' using errcode = '55000';
  elsif old.status = 'pending' and new.status = 'cancelled'
    and old.provider_status <> 'not_started' then
    raise exception 'An executed account change requires reconciliation.' using errcode = '55000';
  end if;
  return new;
end;
$$;

create trigger portal_account_status_executor_guard
before update on private.portal_account_status_change_claims
for each row execute function private.guard_portal_account_status_executor();
revoke all on function private.guard_portal_account_status_executor() from public, anon, authenticated;

-- The begin RPC's change_token identifies an operation; it is NOT permission
-- to call Auth. Only this atomic, server-only take grants one execution. Even
-- replaying the same executor token must not grant execution a second time.
create function public.claim_portal_account_status_execution(
  p_auth_user_id uuid,
  p_change_token uuid,
  p_actor_user_id uuid,
  p_executor_token uuid
)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_claim private.portal_account_status_change_claims;
begin
  if p_executor_token is null or p_actor_user_id is null then
    raise exception 'An account executor and actor are required.' using errcode = '22004';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('portal_account:' || p_auth_user_id::text, 0));
  select claim.* into v_claim
  from private.portal_account_status_change_claims claim
  where claim.auth_user_id = p_auth_user_id
    and claim.change_token = p_change_token
    and claim.claimed_by = p_actor_user_id
  for update;
  if not found or v_claim.status = 'cancelled' then
    raise exception 'The account-status claim is no longer valid.' using errcode = '40001';
  end if;
  if v_claim.status = 'finalised' then return 'finalised'; end if;
  if v_claim.provider_status <> 'not_started' then return v_claim.provider_status; end if;

  update private.portal_account_status_change_claims
  set provider_status = 'executing', executor_token = p_executor_token,
      provider_started_at = clock_timestamp()
  where auth_user_id = p_auth_user_id;
  return 'execute';
end;
$$;

-- Receipt writes are safe to retry. They never call Auth and are bound to the
-- exact executor. Auth success must be observed before recording succeeded.
create function public.record_portal_account_status_execution(
  p_auth_user_id uuid,
  p_change_token uuid,
  p_executor_token uuid,
  p_succeeded boolean
)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_claim private.portal_account_status_change_claims;
begin
  if p_succeeded is null then raise exception 'An outcome is required.' using errcode = '22004'; end if;
  perform pg_advisory_xact_lock(hashtextextended('portal_account:' || p_auth_user_id::text, 0));
  select claim.* into v_claim
  from private.portal_account_status_change_claims claim
  where claim.auth_user_id = p_auth_user_id and claim.change_token = p_change_token
    and claim.executor_token = p_executor_token
  for update;
  if not found then return false; end if;
  if v_claim.provider_status = (case when p_succeeded then 'succeeded' else 'unknown' end) then
    return true;
  end if;
  if v_claim.status <> 'pending' or v_claim.provider_status <> 'executing' then return false; end if;
  update private.portal_account_status_change_claims
  set provider_status = case when p_succeeded then 'succeeded' else 'unknown' end,
      provider_finished_at = clock_timestamp()
  where auth_user_id = p_auth_user_id;
  return true;
end;
$$;

-- Recover a lost begin/finalise response using the original request identity.
-- This returns state only, never an execution grant. Unknown/executing claims
-- have no timeout/lease takeover: reading banned_until cannot rule out a late
-- Auth write. Recovery of those claims requires provider completion evidence
-- and termination of the original executor, through an approved operator path.
create function public.inspect_portal_account_status_request(
  p_person_id uuid,
  p_auth_user_id uuid,
  p_enabled boolean,
  p_expected_account_version bigint
)
returns table (change_token uuid, claim_status text, provider_status text)
language sql
stable
security definer
set search_path = ''
as $$
  select claim.change_token, claim.status, claim.provider_status
  from private.portal_account_status_change_claims claim
  join public.profiles profile on profile.id = claim.auth_user_id
  join public.internal_org_people person on person.id = claim.person_id
    and person.auth_user_id = claim.auth_user_id
  where private.is_portal_account_admin()
    and claim.claimed_by = (select auth.uid())
    and claim.person_id = p_person_id and claim.auth_user_id = p_auth_user_id
    and claim.requested_enabled = p_enabled
    and (
      claim.claimed_account_version = p_expected_account_version
      or (
        -- Archiving commits the disabled profile/version before finalisation.
        -- Permit database-only recovery using that current version, never an
        -- arbitrary stale/current version or an unconfirmed Auth execution.
        claim.provider_status = 'succeeded'
        and claim.status in ('pending', 'finalised')
        and not claim.requested_enabled and not person.is_active
        and profile.account_status = 'disabled'
        and profile.account_version = claim.claimed_account_version + 1
        and p_expected_account_version = profile.account_version
      )
    );
$$;

revoke all on function public.claim_portal_account_status_execution(uuid, uuid, uuid, uuid)
  from public, anon, authenticated;
revoke all on function public.record_portal_account_status_execution(uuid, uuid, uuid, boolean)
  from public, anon, authenticated;
revoke all on function public.inspect_portal_account_status_request(uuid, uuid, boolean, bigint)
  from public, anon, authenticated;
grant execute on function public.claim_portal_account_status_execution(uuid, uuid, uuid, uuid) to service_role;
grant execute on function public.record_portal_account_status_execution(uuid, uuid, uuid, boolean) to service_role;
grant execute on function public.inspect_portal_account_status_request(uuid, uuid, boolean, bigint) to authenticated;

-- Creation compensation is permitted only after a definite SQL rejection and
-- an exact identity read-back. A durable reservation closes the gap between the
-- final orphan check and the separate Auth DELETE. An uncertain DELETE leaves
-- the reservation in place for operator recovery; it is never auto-released.
create table private.portal_account_creation_cleanup (
  auth_user_id uuid primary key references auth.users(id) on delete cascade,
  reserved_at timestamptz not null default clock_timestamp()
);
alter table private.portal_account_creation_cleanup enable row level security;
revoke all on table private.portal_account_creation_cleanup from public, anon, authenticated;

create function private.prevent_linking_portal_account_during_cleanup()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid;
begin
  if tg_table_name = 'profiles' then
    if new.login_name is null then return new; end if;
    v_user_id := new.id;
  else
    v_user_id := new.auth_user_id;
  end if;
  if v_user_id is null then return new; end if;
  perform pg_advisory_xact_lock(hashtextextended('portal_account:' || v_user_id::text, 0));
  if exists (select 1 from private.portal_account_creation_cleanup c where c.auth_user_id = v_user_id) then
    raise exception 'This unlinked account is reserved for cleanup.' using errcode = '55000';
  end if;
  return new;
end;
$$;
create trigger portal_account_cleanup_person_guard
before insert or update of auth_user_id on public.internal_org_people
for each row execute function private.prevent_linking_portal_account_during_cleanup();
create trigger portal_account_cleanup_profile_guard
before insert or update of login_name on public.profiles
for each row execute function private.prevent_linking_portal_account_during_cleanup();
revoke all on function private.prevent_linking_portal_account_during_cleanup() from public, anon, authenticated;

create function public.reserve_portal_account_creation_cleanup(p_auth_user_id uuid, p_auth_email text)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform pg_advisory_xact_lock(hashtextextended('portal_account:' || p_auth_user_id::text, 0));
  if not exists (
    select 1 from auth.users u where u.id = p_auth_user_id and u.email = p_auth_email
      and u.email ~ '^portal-[0-9a-f-]{36}@accounts[.]mobilityaccess[.]com[.]au$'
  ) or exists (
    select 1 from public.internal_org_people p where p.auth_user_id = p_auth_user_id
  ) or exists (
    select 1 from public.profiles p where p.id = p_auth_user_id and p.login_name is not null
  ) or exists (
    select 1 from private.portal_account_admins a where a.auth_user_id = p_auth_user_id
  ) then return false;
  end if;
  insert into private.portal_account_creation_cleanup(auth_user_id) values (p_auth_user_id)
  on conflict (auth_user_id) do nothing;
  return true;
end;
$$;
revoke all on function public.reserve_portal_account_creation_cleanup(uuid, text) from public, anon, authenticated;
grant execute on function public.reserve_portal_account_creation_cleanup(uuid, text) to service_role;

commit;
